/**
 * Base rule engine error class
 */
export class RuleEngineError extends Error {
    constructor(message: any, operator?: null, context?: {}, originalError?: null);
    operator: any;
    context: {};
    originalError: any;
    timestamp: string;
    toJSON(): {
        name: string;
        message: string;
        operator: any;
        context: {};
        timestamp: string;
    };
}
/**
 * Validation specific error
 */
export class ValidationError extends RuleEngineError {
    constructor(message: any, context?: {});
}
/**
 * Operator specific error
 */
export class OperatorError extends RuleEngineError {
    constructor(message: any, operator: any, context?: {}, originalError?: null);
}
